import { Link } from "react-router-dom"

const DummyEvents = [
    { id: 'e1', title: "EVENT 1" },
    { id: 'e2', title: "EVENT 2" },
    { id: 'e3', title: "EVENT 3" },
    { id: 'e4', title: "EVENT 4" },
    { id: 'e5', title: "EVENT 5" },
    { id: 'e6', title: "EVENT 6" },
    { id: 'e7', title: "EVENT 7" }
]

export default function EventsPage() {
    console.log("events")
    return (
        <ul>
            {DummyEvents.map((event) =>
            (<li key={event.id}>
                <Link to={event.id} />
            </li>)
            )}
        </ul>
    )
}
